/**
 * Bubble Sort Implementation for Integer Arrays
 * 
 * Constraints:
 * - Maximum array length: 100 elements
 * - Integer range: [-10,000, 10,000]
 * - Sorts in ascending order
 */

/**
 * Validates input array against constraints
 * @param {*} arr - Input to validate
 * @throws {TypeError|RangeError} Detailed error messages for invalid inputs
 */
function validateInput(arr) {
  // Check if input is actually an array
  if (!Array.isArray(arr)) {
    throw new TypeError('Input must be an array. Received: ' + typeof arr);
  }

  // Check maximum length constraint (100 elements)
  if (arr.length > 100) {
    throw new RangeError(
      `Array length (${arr.length}) exceeds maximum allowed length of 100 elements`
    );
  }

  // Validate each element
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];

    // Check if element is an integer (not float, not string, not NaN)
    if (!Number.isInteger(element)) {
      throw new TypeError(
        `Element at index ${i} (${JSON.stringify(element)}) is not an integer. ` +
        `Type: ${typeof element}, Value: ${element}`
      );
    }

    // Check range constraint [-10000, 10000]
    if (element < -10000 || element > 10000) {
      throw new RangeError(
        `Element at index ${i} (${element}) is outside valid range [-10000, 10000]`
      );
    }
  }
}

/**
 * Bubble Sort Algorithm
 * 
 * Algorithm Logic:
 * 1. Iterate through the array from start to end
 * 2. Compare each pair of adjacent elements
 * 3. Swap them if they are in the wrong order (left > right)
 * 4. After each full pass, the largest unsorted element "bubbles up" to its correct position
 * 5. Optimization: Track if any swaps occurred; if no swaps, array is already sorted
 * 
 * Time Complexity:
 * - Best Case: O(n) - When array is already sorted (with optimization)
 * - Average Case: O(n²) - Random order
 * - Worst Case: O(n²) - When array is reverse sorted
 * 
 * Space Complexity: O(1) - Sorts in-place with constant extra memory
 * Stability: Yes - Maintains relative order of equal elements
 * 
 * @param {number[]} arr - Array of integers to sort (modified in-place)
 * @returns {number[]} The sorted array (same reference)
 */
function bubbleSort(arr) {
  const n = arr.length;

  // Outer loop: controls the number of passes
  // After pass i, the i largest elements are in their final positions
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;

    // Inner loop: compares adjacent elements
    // We subtract i because the last i elements are already sorted
    // We subtract 1 to avoid comparing the last element with undefined
    for (let j = 0; j < n - i - 1; j++) {
      // Compare adjacent elements
      if (arr[j] > arr[j + 1]) {
        // Swap using array destructuring (ES6)
        // This places the larger element to the right
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        swapped = true;
      }
    }

    // Optimization: If no swaps occurred in this pass, 
    // the array is already sorted and we can exit early
    if (!swapped) {
      break;
    }
  }

  return arr;
}

/**
 * Main sorting function with validation and error handling
 * Returns a result object to safely handle errors without throwing
 * 
 * @param {number[]} inputArray - Array of integers to sort
 * @returns {Object} Result object containing:
 *   - success: boolean indicating if operation succeeded
 *   - data: sorted array (if success)
 *   - error: error details (if !success)
 *   - meta: additional information about the operation
 */
function sortArray(inputArray) {
  try {
    // Step 1: Validate input constraints
    validateInput(inputArray);

    // Step 2: Handle edge cases
    if (inputArray.length === 0) {
      return {
        success: true,
        data: [],
        meta: { message: 'Empty array provided', comparisons: 0 }
      };
    }

    if (inputArray.length === 1) {
      return {
        success: true,
        data: [...inputArray], // Return copy to avoid external mutation
        meta: { message: 'Single element array', comparisons: 0 }
      };
    }

    // Step 3: Create a copy to avoid mutating the original array
    // (Functional programming approach - pure function)
    const workingArray = [...inputArray];

    // Step 4: Execute bubble sort
    const sortedArray = bubbleSort(workingArray);

    return {
      success: true,
      data: sortedArray,
      meta: {
        message: 'Array sorted successfully',
        algorithm: 'Bubble Sort',
        complexity: 'O(n²) worst case, O(n) best case',
        inputLength: inputArray.length
      }
    };

  } catch (error) {
    // Return error details without crashing
    return {
      success: false,
      data: null,
      error: {
        type: error.name,
        message: error.message,
        constraint: error.name === 'RangeError' ? 'value/length constraint' : 
                   error.name === 'TypeError' ? 'type constraint' : 'unknown'
      }
    };
  }
}

